const materialReuse=[
 ['joseon-foundation','joseon',0,'향교의 주요 역할은 무엇인가요?','지방에서 유교를 가르치고 인재를 기르는 일','지방의 군대를 모아 전투를 지휘하는 일','항구에 들어온 외국 상인의 물건을 검사하는 일','조선은 지방에 향교를 두어 유교 경전을 가르쳤다. 유생들은 이곳에서 공부하며 과거를 준비하기도 했다. 향교에는 공자와 유학자에게 제사를 지내는 공간도 있었다.','향교는 지방의 유교 교육과 제례를 담당한 기관입니다.','https://contents.history.go.kr/front/km/view.do?levelId=km_039_0060_0030_0030_0020','국사편찬위원회 · 향교'],
 ['joseon-science','joseon',2,'훈민정음 해례본에서 알아볼 수 있는 것은 무엇인가요?','새 글자를 만든 원리와 사용하는 방법','조선의 모든 고을에서 거둔 세금 액수','왕이 날마다 신하에게 내린 모든 명령','세종은 백성이 자신의 뜻을 글로 쉽게 나타낼 수 있도록 훈민정음을 만들었다. 훈민정음 해례본에는 글자를 만든 원리와 글자를 조합하고 사용하는 방법이 설명되어 있다. 글자의 이름만 적은 목록과는 다르다.','해례본은 훈민정음의 창제 원리와 사용법을 설명한 책입니다.','https://contents.history.go.kr/play/view.do?levelId=ts_b33','국사편찬위원회 · 훈민정음 해례본'],
 ['joseon-life','joseon',3,'조선왕조실록을 활용하기에 알맞은 조사 주제는 무엇인가요?','조선에서 있었던 사건과 나라의 정책','조선의 모든 가정이 날마다 먹은 음식','조선의 모든 주민이 남긴 개인 편지','조선왕조실록에는 왕의 재위 기간에 일어난 중요한 일들이 날짜순으로 정리되어 있다. 정치뿐 아니라 경제와 사회, 자연현상 등에 관한 내용도 남아 있다. 실록의 기록을 읽으면 당시의 사건과 나라의 대응을 살펴볼 수 있다.','실록은 당시 사건과 정책을 살피는 자료이며 모든 가정의 일상을 빠짐없이 기록한 것은 아닙니다.','https://sillok.history.go.kr/intro/intro.do','국사편찬위원회 · 조선왕조실록'],
 ['joseon-life','joseon',5,'장시가 사람들의 생활에 한 역할은 무엇인가요?','필요한 물건을 사고팔며 소식을 주고받게 했다','관리 시험의 답안을 정해 주었다','주민의 토지를 모두 같은 넓이로 나누었다','조선 시대 장시에는 농민과 상인 등 여러 사람이 모였다. 사람들은 곡식과 옷감, 생활 도구 등을 사고팔았다. 장에 오간 사람들을 통해 다른 마을의 소식도 전해졌다. 장시는 물건과 정보가 오가는 장소였다.','장시는 물건 거래와 정보 교류가 이루어지는 장소였습니다.','https://contents.history.go.kr/mobile/ta/view.do?levelId=ta_m31_0090_0020','국사편찬위원회 · 조선 후기 생활'],
 ['joseon-late-culture','joseon',4,'풍속화가 역사 연구에 도움이 되는 까닭은 무엇인가요?','일하고 쉬고 즐기는 사람들의 생활을 살펴볼 수 있어서','그림 속 인물의 실제 이름과 나이를 모두 알 수 있어서','그림 한 점에 전국의 생활이 빠짐없이 담겨 있어서','조선 후기에는 농사짓는 모습, 장터의 사람들, 놀이를 즐기는 장면 등을 담은 풍속화가 그려졌다. 화가는 생활 속 장면을 골라 인물의 자세와 표정, 주변 도구를 표현했다. 이런 그림은 당시의 생활과 문화를 알아보는 자료가 된다.','풍속화의 인물과 활동, 도구를 통해 당시 생활을 살펴볼 수 있습니다.','https://contents.history.go.kr/mobile/ta/view.do?levelId=ta_m31_0090_0020','국사편찬위원회 · 조선 후기 문화'],
 ['independence-1919','modern',0,'3·1 독립 선언서에 담긴 뜻은 무엇인가요?','조선이 독립국이며 스스로 나라의 일을 결정할 권리가 있다는 뜻','일본의 식민 통치를 계속 받아들이겠다는 뜻','관리 몇 사람의 교체만으로 독립을 대신하겠다는 뜻','1919년 3월 1일 발표된 독립 선언서는 조선이 독립국이며 조선인이 자주적인 민족임을 밝혔다. 독립을 되찾으려는 뜻을 널리 알리고, 독립운동을 질서 있게 펼칠 것을 당부했다.','선언서는 조선의 독립과 민족의 자주적인 권리를 알렸습니다.','https://theme.archives.go.kr/next/nationalArchives/subPage/nationalArchives11.do','국가기록원 · 3·1운동 관련 독립선언서류'],
 ['independence-1919','modern',1,'3·1 운동의 특징으로 알맞은 것은 무엇인가요?','여러 지역과 계층의 사람들이 참여했다','서울에 사는 한 계층만 참여했다','각 지역이 같은 장소에서만 시위를 했다','3·1 운동은 도시뿐 아니라 장터와 마을 등 여러 곳으로 퍼졌다. 학생과 종교인, 농민과 상인 등 다양한 사람들이 독립 만세를 외쳤다. 참여한 사람들과 시위가 벌어진 장소는 지역마다 달랐다.','지역과 계층을 넓혀 많은 사람이 독립운동에 참여했습니다.','https://contents.history.go.kr/front/ta/view.do?levelId=ta_m42_0050_0030','국사편찬위원회 · 3·1 운동'],
 ['independence-struggle','modern',2,'이 글에서 알 수 있는 윤봉길의 모습은 무엇인가요?','독립운동을 앞두고 가족과 다음 세대에게 뜻을 전했다','독립운동과 관계없이 학교 시험의 답만 남겼다','자신의 뜻이 담긴 글을 남기지 않았다','윤봉길은 1932년 상하이 의거를 앞두고 두 아들과 청년들에게 남기는 글을 썼다. 이 글들은 독립운동가가 어떤 뜻을 품고 있었는지 살피는 자료이다. 작성한 사람과 시기를 알면 글의 배경을 함께 이해할 수 있다.','가족과 청년에게 남긴 글에서 독립운동가의 생각과 뜻을 살펴볼 수 있습니다.','https://learn.i815.or.kr/0201/learning/exhibit/avXFPyVP3TXrlwcPiAb/view','독립기념관 · 윤봉길 자료'],
 ['republic-founding','modern',3,'사건의 순서가 알맞은 것은 무엇인가요?','광복 → 제헌 국회 구성 → 대한민국 정부 수립','대한민국 정부 수립 → 광복 → 제헌 국회 구성','제헌 국회 구성 → 대한민국 정부 수립 → 광복','1945년 광복을 맞은 뒤 새로운 나라를 세우기 위한 논의가 이어졌다. 1948년 5월 10일 총선거로 제헌 국회가 구성되었고, 국회는 헌법을 제정했다. 같은 해 8월 15일 대한민국 정부 수립이 선포되었다.','광복 뒤 제헌 국회가 구성되었으며 헌법 제정에 이어 정부가 수립되었습니다.','https://contents.history.go.kr/mobile/eh/list.do?code=eh_age_50','국사편찬위원회 · 대한민국 정부 수립'],
 ['korean-war','modern',5,'흥남 철수에서 피란민들의 이동은 무엇을 보여 주나요?','전쟁으로 살던 곳을 떠나 안전한 곳을 찾아야 했던 어려움','전쟁과 관계없이 모두 관광을 떠난 모습','집과 일터를 그대로 둔 채 매일 통근한 모습','1950년 12월 흥남항에는 전쟁을 피해 남쪽으로 가려는 사람들이 모였다. 피란민들은 배에 올라 살던 곳을 떠났다. 새로운 곳에 도착한 뒤에도 머물 집과 생계를 마련해야 하는 어려움이 이어졌다.','피란은 전쟁 때문에 삶터를 떠나 안전한 곳과 새로운 생활을 찾아야 했던 경험입니다.','https://unarchives.mpva.go.kr/contents/xmas','국가보훈부 · 흥남 철수'],
 ['korean-war','modern',6,'이산가족의 어려움으로 알맞은 것은 무엇인가요?','헤어진 가족의 소식을 알거나 만나기 어려웠다','모든 가족이 같은 마을로 함께 이사했다','가족이 언제나 자유롭게 남북을 오갔다','6·25 전쟁과 분단으로 가족이 남과 북에 흩어지기도 했다. 전쟁 중에 헤어진 뒤 서로의 생사를 모른 채 오랫동안 지낸 가족도 있었다. 전투가 멈춘 뒤에도 자유롭게 오갈 수 없어 가족을 만나기 어려웠다.','전쟁과 분단은 가족의 만남과 소식 확인에도 오랜 어려움을 남겼습니다.','https://unikorea.go.kr/web/unikorea/contents/reunion_current','통일부 · 이산가족'],
 ['colonial-life','modern',10,'글에 나타난 일제의 정책은 무엇을 목적으로 했나요?','우리 민족의 문화를 억누르고 일본에 동화시키려 했다','우리말 교육과 역사 연구를 넓히려 했다','조선인이 나라의 일을 스스로 결정하도록 했다','일제 강점기 후반 일제는 학교에서 일본어 사용을 강요하고 우리 역사 교육을 억눌렀다. 일본식 성과 이름을 쓰도록 강요하기도 했다. 우리말과 역사를 지키려는 사람들은 이러한 정책에 맞서 활동했다.','언어와 역사, 이름에 대한 억압은 우리 민족을 일본에 동화시키려는 정책과 연결됩니다.','https://contents.history.go.kr/id/ta_m71_0100_0010_0030_0010','국사편찬위원회 · 민족 말살 정책']
];
for(const [id,topic,index,prompt,answer,w1,w2,detail,explanation,source,sourceLabel] of materialReuse){const b=banks.find(b=>b.id===id),q=core.historyEvidenceItems(topic)[index];if(!q)throw Error('Missing historical passage: '+topic+'/'+index);
 b.items.push({...q,evidenceId:'material-'+q.id,legacyMaterialId:q.id,reviewedMaterial:true,prompt,answer,choices:[answer,w1,w2],detail,explanation,source,sourceLabel});
}

